   157→export function buildWorkspaceSectionHeaderSegment(
   158→  workspaceId: string,
   159→  section: WorkspaceSection,
   160→  buildLabel?: (titleKey: string, fallbackLabel: string) => string
   161→): DesktopBreadcrumbSegment {
   162→  const descriptor = getWorkspaceSectionDescriptor(section);
   163→  const routePath = descriptor?.routePath ?? section;
   164→
   165→  return {
   166→    id: `workspace:${workspaceId}:${section}`,
   167→    label: descriptor
   168→      ? buildLabel?.(descriptor.titleKey, descriptor.fallbackLabel) ??
   169→        descriptor.fallbackLabel
   170→      : section,
   171→    href: `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`,
   172→    icon: descriptor?.icon,
   173→    descriptorId: `workspace-section:${section}`,
   174→    meta: {
   175→      workspaceId,
   176→      section,
   177→      routePath,
   178→    },
   179→  };
   180→}
