   228→export function createStaticWorkspaceIndexNodes(
   229→  workspaceId: string
   230→): VirtualPageIndexNode[] {
   231→  const root = createWorkspaceRootNode(workspaceId);
   232→  const sectionNodes = WORKSPACE_SECTION_DESCRIPTORS.map((section, index) => ({
   233→    id: `${root.id}:${section.section}`,
   234→    descriptorId: section.id,
   235→    label: section.fallbackLabel,
   236→    icon: section.icon,
   237→    parentId: root.id,
   238→    order: index + 1,
   239→    target: {
   240→      key: `workspace:${workspaceId}:${section.section}`,
   241→      canonicalUrl: `/workspace/${encodeURIComponent(workspaceId)}/${section.routePath}`,
   242→      location: {
   243→        kind: "workspace-section" as const,
   244→        workspaceId,
   245→        section: section.section,
   246→      },
   247→    },
   248→  }));
   249→
   250→  return [root, ...sectionNodes];
   251→}
