   253→export function resolveSegmentDescriptorId(
   254→  segment: DesktopBreadcrumbSegment
   255→): string | undefined {
   256→  if (segment.descriptorId) {
   257→    return segment.descriptorId;
   258→  }
   259→
   260→  if (/^\/workspace\/[^/]+$/.test(segment.href)) {
   261→    return "workspace";
   262→  }
   263→
   264→  const sectionMatch = segment.href.match(
   265→    /^\/workspace\/[^/]+\/(chat|kanban|cron|ideas|files|github|chat-monitor)$/
   266→  );
   267→  if (sectionMatch) {
   268→    return `workspace-section:${sectionMatch[1]}`;
   269→  }
   270→
   271→  if (/^\/workspace\/[^/]+\/(agent|agents)$/.test(segment.href)) {
   272→    return "workspace-section:agent";
   273→  }
   274→
   275→  if (/^\/agent\/[^/]+/.test(segment.href)) {
   276→    return "workspace-agent";
   277→  }
   278→
   279→  if (/^\/executor\/[^/]+/.test(segment.href)) {
   280→    return "workspace-executor";
   281→  }
   282→
   283→  return undefined;
   284→}
