   286→export function buildRootDropdownItems({
   287→  workspaces = [],
   288→  currentArea = "home",
   289→  activeWorkspaceId,
   290→  currentSection,
   291→  activeHref,
   292→  buildLabel,
   293→  onSelectWorkspace,
   294→  labelGlobalWorkspace,
   295→}: {
   296→  workspaces?: WorkspaceListItemLike[];
   297→  currentArea?: "home" | "apps" | "section";
   298→  activeWorkspaceId?: string;
   299→  currentSection?: WorkspaceSection;
   300→  activeHref?: string;
   301→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   302→  onSelectWorkspace?: (workspaceId: string) => void;
   303→  labelGlobalWorkspace?: string;
   304→}): BreadcrumbDropdownItem[] {
   305→  const sectionRoutePath = currentSection
   306→    ? getWorkspaceSectionRoutePath(currentSection)
   307→    : "";
   308→
   309→  const workspaceItems = buildDropdownItems(workspaces, (workspace) => {
   310→    const workspaceLabel =
   311→      workspace.type === "global"
   312→        ? labelGlobalWorkspace ??
   313→          buildLabel?.("workspace.global", "Global Workspace") ??
   314→          "Global Workspace"
   315→        : workspace.name;
   316→    const href =
   317→      currentArea === "apps"
   318→        ? `/workspace/${encodeURIComponent(workspace.id)}/apps`
   319→        : sectionRoutePath
   320→          ? `/workspace/${encodeURIComponent(workspace.id)}/${sectionRoutePath}`
   321→          : `/workspace/${encodeURIComponent(workspace.id)}`;
   322→
   323→    return {
   324→      id: `workspace:${workspace.id}`,
   325→      label: workspaceLabel,
   326→      href,
   327→      description: workspace.path,
   328→      icon: {
   329→        type: "lucide",
   330→        value: workspace.type === "global" ? "globe" : "folder-open",
   331→      } as IconData,
   332→      isActive: workspace.id === activeWorkspaceId,
   333→      descriptorId: "workspace",
   334→      meta: {
   335→        workspaceId: workspace.id,
   336→        section: currentSection,
   337→        routePath: sectionRoutePath || undefined,
   338→      },
   339→      onSelect: onSelectWorkspace
   340→        ? () => onSelectWorkspace(workspace.id)
   341→        : undefined,
   342→    };
   343→  });
   344→
   345→  const systemItems = buildDropdownItems(
   346→    [
   347→      {
   348→        id: "root:settings",
   349→        label: getSettingsSectionLabel(),
   350→        href: "/settings/general",
   351→        icon: getSettingsSectionIcon(),
   352→        isActive: activeHref?.startsWith("/settings") ?? false,
   353→      },
   354→      {
   355→        id: "root:documents",
   356→        label: buildLabel?.("nav.documents", "Documents") ?? "Documents",
   357→        href: "/documents",
   358→        icon: { type: "lucide", value: "file-text" } as IconData,
   359→        isActive: activeHref === "/documents",
   360→      },
   361→      {
   362→        id: "root:devices",
   363→        label: buildLabel?.("nav.devices", "Devices") ?? "Devices",
   364→        href: "/devices/pair",
   365→        icon: { type: "lucide", value: "smartphone" } as IconData,
   366→        isActive: activeHref === "/devices/pair",
   367→      },
   368→    ],
   369→    (item) => ({
   370→      ...item,
   371→      descriptorId: item.id.replace("root:", ""),
   372→    })
   373→  );
   374→
   375→  return [...workspaceItems, ...systemItems];
   376→}
