   597→export function resolvePageIndexBranch({
   598→  segment,
   599→  workspaceId,
   600→  workspaces,
   601→  pages,
   602→  activeWorkspaceId,
   603→  currentSection,
   604→  currentArea,
   605→  currentPageSlug,
   606→  currentSettingsSection,
   607→  allowGithub,
   608→  buildLabel,
   609→  onSelectWorkspace,
   610→  onSelectSection,
   611→  labelGlobalWorkspace,
   612→}: ResolvePageIndexBranchInput): BreadcrumbDropdownItem[] {
   613→  const descriptorId = resolveSegmentDescriptorId(segment);
   614→
   615→  // Resolve dropdownCategory from route registry when possible.
   616→  // This enables registry-driven dropdown dispatch alongside legacy descriptorId matching.
   617→  // Future: use dropdownCategory to replace descriptorId-based rule matching entirely.
   618→  const routeMatch = segment.href && segment.href !== "#"
   619→    ? registry.match(segment.href)
   620→    : null;
   621→  void routeMatch?.entry.dropdownCategory;
   622→
   623→  const input: ResolvePageIndexBranchInput = {
   624→    segment,
   625→    workspaceId,
   626→    workspaces,
   627→    pages,
   628→    activeWorkspaceId,
   629→    currentSection,
   630→    currentArea,
   631→    currentPageSlug,
   632→    currentSettingsSection,
   633→    allowGithub,
   634→    buildLabel,
   635→    onSelectWorkspace,
   636→    onSelectSection,
   637→    labelGlobalWorkspace,
   638→  };
   639→
   640→  const rules: BreadcrumbDropdownRule[] = [
   641→    {
   642→      matches: (_input, descriptorId) => descriptorId === "workspace",
   643→      build: (input) =>
   644→        buildRootDropdownItems({
   645→          workspaces: input.workspaces,
   646→          currentArea: input.currentArea,
   647→          activeWorkspaceId: input.activeWorkspaceId,
   648→          currentSection: input.currentSection,
   649→          activeHref: input.segment.href,
   650→          buildLabel: input.buildLabel,
   651→          onSelectWorkspace: input.onSelectWorkspace,
   652→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   653→        }),
   654→    },
   655→    {
   656→      matches: (input, descriptorId) =>
   657→        (descriptorId === "virtual-folder" || descriptorId === "settings") &&
   658→        input.segment.href.startsWith("/settings/") &&
   659→        input.segment.label === getSettingsSectionLabel(),
   660→      build: (input) =>
